'use strict';
/**
 * Parley relay server.
 *
 * The server never sees message plaintext or private keys. It only:
 *   - stores each user's PUBLIC keys,
 *   - verifies users prove ownership of their signing key (challenge/response),
 *   - relays and temporarily queues opaque encrypted envelopes.
 */
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { WebSocketServer } = require('ws');

const PORT = Number(process.env.PORT) || 3000;
const DATA_FILE = process.env.DATA_FILE || path.join(__dirname, 'data.json');

const USERNAME_RE = /^[a-z0-9_]{3,24}$/;
const MAX_WS_PAYLOAD = 8 * 1024 * 1024;
const MAX_CT_LEN = 6 * 1000 * 1000;      // base64 chars (fits a 4 MB photo)
const MAX_QUEUE_PER_USER = 1000;
const MAX_QUEUE_BYTES = 40 * 1024 * 1024; // undelivered data kept per user
const MSG_LIMIT = { count: 30, windowMs: 10_000 };
const REGISTER_LIMIT = { count: 5, windowMs: 60 * 60 * 1000 }; // per IP
const SIG_LIMIT = { count: 300, windowMs: 10_000 };            // call setup messages
const MAX_SIG_CT = 24 * 1024;

// STUN helps two devices find each other. Some networks also need a TURN relay:
// set the ICE_SERVERS environment variable to a JSON list to add one, e.g.
// [{"urls":"stun:stun.l.google.com:19302"},{"urls":"turn:turn.example.com:3478","username":"u","credential":"p"}]
let ICE_SERVERS = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
];
try {
  if (process.env.ICE_SERVERS) ICE_SERVERS = JSON.parse(process.env.ICE_SERVERS);
} catch (_) {
  console.warn('ICE_SERVERS is not valid JSON; using the default STUN servers');
}

// ---------- persistence (small JSON file; swap for a real DB at scale) ----------
let db = { users: {}, queue: {}, push: {} };
try {
  db = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
  db.users ||= {};
  db.queue ||= {};
  db.push ||= {};
} catch (_) { /* first run */ }

let saveTimer = null;
function saveSoon() {
  if (saveTimer) return;
  saveTimer = setTimeout(saveNow, 200);
}
function saveNow() {
  clearTimeout(saveTimer);
  saveTimer = null;
  try {
    const tmp = DATA_FILE + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(db));
    fs.renameSync(tmp, DATA_FILE);
  } catch (err) {
    // Never crash because the disk is read-only or full; keep serving from memory.
    console.error('Could not save data:', err.message);
  }
}
process.on('uncaughtException', err => console.error('Unexpected error:', err));
process.on('unhandledRejection', err => console.error('Unexpected rejection:', err));
process.on('SIGINT', () => { saveNow(); process.exit(0); });
process.on('SIGTERM', () => { saveNow(); process.exit(0); });

// ---------- crypto helpers ----------
function cleanJwk(jwk) {
  if (!jwk || jwk.kty !== 'EC' || jwk.crv !== 'P-256') return null;
  if (typeof jwk.x !== 'string' || typeof jwk.y !== 'string') return null;
  if (jwk.x.length > 64 || jwk.y.length > 64) return null;
  return { kty: 'EC', crv: 'P-256', x: jwk.x, y: jwk.y };
}

function verifySig(signPubJwk, message, sigB64) {
  try {
    const key = crypto.createPublicKey({ key: signPubJwk, format: 'jwk' });
    return crypto.verify(
      'sha256',
      Buffer.from(message, 'utf8'),
      { key, dsaEncoding: 'ieee-p1363' }, // WebCrypto's ECDSA signature format
      Buffer.from(sigB64, 'base64')
    );
  } catch (_) {
    return false;
  }
}

const authMessage = (nonce, username) => `pm-auth-v1:${nonce}:${username}`;

// ---------- push notifications ----------
// "Wake-up" pushes carry NO content: the phone is told only that something arrived, then the
// app connects and fetches the encrypted message itself. The push services see nothing useful.
const PUSH_HOSTS = ['googleapis.com', 'push.services.mozilla.com', 'push.apple.com', 'notify.windows.com'];
const PUSH_EXTRA_HOSTS = (process.env.PUSH_EXTRA_HOSTS || '').split(',').map(s => s.trim()).filter(Boolean);
const VAPID_SUBJECT = process.env.VAPID_SUBJECT || 'mailto:admin@example.com';
const b64u = buf => Buffer.from(buf).toString('base64url');
let vapidPrivate;   // KeyObject
let vapidPublic;    // base64url, uncompressed P-256 point (what browsers subscribe with)

function loadVapid() {
  let jwk;
  if (process.env.VAPID_PRIVATE && process.env.VAPID_PUBLIC) {
    const pub = Buffer.from(process.env.VAPID_PUBLIC, 'base64url');
    jwk = { kty: 'EC', crv: 'P-256', x: b64u(pub.subarray(1, 33)), y: b64u(pub.subarray(33, 65)), d: process.env.VAPID_PRIVATE };
  } else if (db.vapid && db.vapid.jwk) {
    jwk = db.vapid.jwk;
  } else {
    const { privateKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
    jwk = privateKey.export({ format: 'jwk' });
    db.vapid = { jwk };
    saveSoon();
    const pub = b64u(Buffer.concat([Buffer.from([4]), Buffer.from(jwk.x, 'base64url'), Buffer.from(jwk.y, 'base64url')]));
    console.log('Generated new notification keys. To keep them across restarts, set these environment variables:');
    console.log('  VAPID_PUBLIC=' + pub);
    console.log('  VAPID_PRIVATE=' + jwk.d);
  }
  vapidPrivate = crypto.createPrivateKey({ key: jwk, format: 'jwk' });
  vapidPublic = b64u(Buffer.concat([Buffer.from([4]), Buffer.from(jwk.x, 'base64url'), Buffer.from(jwk.y, 'base64url')]));
}
loadVapid();

// Only genuine browser push services are allowed (stops the server being used to call arbitrary URLs)
function pushEndpointOk(ep) {
  try {
    const u = new URL(ep);
    if (PUSH_EXTRA_HOSTS.includes(u.hostname)) return true;
    return u.protocol === 'https:' && PUSH_HOSTS.some(h => u.hostname === h || u.hostname.endsWith('.' + h));
  } catch (_) { return false; }
}

function vapidHeader(endpoint) {
  const head = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  const body = b64u(JSON.stringify({
    aud: new URL(endpoint).origin,
    exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: VAPID_SUBJECT,
  }));
  const sig = crypto.sign('sha256', Buffer.from(`${head}.${body}`), { key: vapidPrivate, dsaEncoding: 'ieee-p1363' });
  return `vapid t=${head}.${body}.${b64u(sig)}, k=${vapidPublic}`;
}

const lastPush = new Map();
async function notifyUser(username) {
  const now = Date.now();
  if (now - (lastPush.get(username) || 0) < 5000) return;
  lastPush.set(username, now);
  for (const endpoint of [...(db.push[username] || [])]) {
    try {
      const res = await fetch(endpoint, {
        method: 'POST',
        headers: { Authorization: vapidHeader(endpoint), TTL: '3600', Urgency: 'high', Topic: 'new-message' },
        signal: AbortSignal.timeout(8000),
      });
      if (res.status === 404 || res.status === 410) {   // subscription no longer exists
        db.push[username] = (db.push[username] || []).filter(e => e !== endpoint);
        saveSoon();
      }
    } catch (_) { /* push service unreachable; the message is still queued */ }
  }
}

function onPush(ws, m) {
  const ep = String(m.endpoint || '');
  if (!ep || ep.length > 700 || !pushEndpointOk(ep)) return;
  for (const [user, list] of Object.entries(db.push)) {          // one browser = one account
    if (user !== ws.user && list.includes(ep)) db.push[user] = list.filter(e => e !== ep);
  }
  const mine = (db.push[ws.user] ||= []);
  if (!mine.includes(ep)) { mine.push(ep); if (mine.length > 5) mine.shift(); }
  saveSoon();
}

function onUnpush(ws, m) {
  const ep = String(m.endpoint || '');
  if (db.push[ws.user]) { db.push[ws.user] = db.push[ws.user].filter(e => e !== ep); saveSoon(); }
}

// ---------- password sign-in (for using an account on another device) ----------
// The browser locks the account's private keys with a key derived from the password and uploads
// only that locked copy ("vault") plus a hash of a separate login token. The server never sees the
// password or the unlocked keys, and hands the vault out only for the right token, with rate limits.
const LOGIN_FAIL_WINDOW = 15 * 60 * 1000;
const loginFails = new Map();

function failures(key) {
  const now = Date.now();
  const list = (loginFails.get(key) || []).filter(t => now - t < LOGIN_FAIL_WINDOW);
  loginFails.set(key, list);
  return list;
}
const noteFail = key => failures(key).push(Date.now());

function parseLogin(l) {
  if (!l || typeof l.token !== 'string' || !/^[A-Za-z0-9+/]{43}=$/.test(l.token)) return null;
  const v = l.vault;
  if (!v || typeof v.iv !== 'string' || typeof v.ct !== 'string' || !v.ct || v.iv.length > 32 || v.ct.length > 12000) return null;
  return { hash: crypto.createHash('sha256').update(l.token).digest('hex'), vault: { iv: v.iv, ct: v.ct } };
}

const DUMMY_HASH = crypto.createHash('sha256').update('no-such-user').digest();

function onGetVault(ws, m, ip) {
  const username = String(m.username || '');
  const token = String(m.token || '');
  const userKey = 'u:' + username;
  const ipKey = 'i:' + ip;
  if (failures(userKey).length >= 10 || failures(ipKey).length >= 30) {
    return send(ws, { t: 'error', code: 'rate_limited_login' });
  }
  const user = db.users[username];
  const stored = user && user.login ? Buffer.from(user.login.hash, 'hex') : DUMMY_HASH;
  const given = crypto.createHash('sha256').update(token).digest();
  const match = crypto.timingSafeEqual(stored, given) && !!(user && user.login);
  if (!match) {
    noteFail(userKey);
    noteFail(ipKey);
    return send(ws, { t: 'error', code: 'bad_login' });   // same answer for "no such user" and "wrong password"
  }
  loginFails.delete(userKey);
  send(ws, { t: 'vault', vault: user.login.vault });
}

function onSetLogin(ws, m) {
  const login = parseLogin(m.login);
  if (!login) return send(ws, { t: 'error', code: 'bad_login_data' });
  db.users[ws.user].login = login;
  saveSoon();
}

