// App name: set the APP_NAME environment variable to rename the app (max 24 characters).
const APP_NAME = (process.env.APP_NAME || 'Parley').replace(/[<>&"'`\{}]/g, '').trim().slice(0, 24) || 'Parley';
const RENDERED = {};
for (const n of ['index.html', 'manifest.webmanifest']) {
  RENDERED[n] = FILES[n].split('{{APP_NAME}}').join(APP_NAME);
}

const server = http.createServer((req, res) => {
  let urlPath;
  try { urlPath = decodeURIComponent(new URL(req.url, 'http://x').pathname); }
  catch (_) { res.writeHead(400); return res.end(); }

  if (urlPath === '/healthz') {   // quick check that the newest version is live
    res.writeHead(200, { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' });
    return res.end('ok: Parley server running (password sign-in build)');
  }
  if (urlPath === '/') urlPath = '/index.html';
  const name = urlPath.slice(1);
  if (!Object.prototype.hasOwnProperty.call(FILES, name)) {
    res.writeHead(404, SECURITY_HEADERS);
    return res.end('Not found');
  }
  res.writeHead(200, {
    ...SECURITY_HEADERS,
    'Content-Type': MIME[path.extname(name)] || 'application/octet-stream',
  });
  res.end(RENDERED[name] || FILES[name]);
});

// ---------- WebSocket relay ----------
